"""QQ-预制图像参考：一个节点挑姿态 / 脸模 / 服装参考图，合成一个批次输出。

每个类型都能选多张，输出是**一个** ``IMAGE``，按 姿态 → 脸模 → 服装 的顺序
把选中的图依次拼成批次（``B`` 维就是张数），后面接 ControlNet / 参考图节点时
一张一张按顺序用。

选「未使用」或一张都没选时输出阻塞，下游分支直接跳过。
图片尺寸不一致时统一缩放到第一张的尺寸，保证能拼成一个批次。

图片全部放在用户目录（见 ``guli_pose_db``），插件目录只放代码。
"""

from __future__ import annotations

from typing import Any

try:  # 包内导入（ComfyUI 正常加载）
    from . import guli_pose_db as db
except ImportError:  # pragma: no cover - 测试里按独立模块加载
    import guli_pose_db as db  # type: ignore[no-redef]

try:
    from comfy_execution.graph import ExecutionBlocker
except Exception:  # pragma: no cover
    ExecutionBlocker = None

#: 多选的存储分隔符：三个字符串控件里放的就是 ``名1|名2|名3``。
SEP = "|"
#: 输出顺序：这个顺序也决定了批次里图片的排列顺序。
LANES = (("pose", "姿态"), ("face", "脸模"), ("cloth", "服装"))


def _blocker() -> Any:
    return ExecutionBlocker(None) if ExecutionBlocker is not None else None


def _choices(lib: str) -> list[str]:
    """这一路可选的条目；库坏了也不能让节点注册失败。"""
    try:
        return db.labels(lib)
    except Exception:
        return [db.UNUSED]


def _split(raw: Any) -> list[str]:
    """把 ``名1|名2`` 拆成列表；去空、去重、保序。"""
    text = str(raw or "")
    seen: list[str] = []
    for piece in text.split(SEP):
        name = piece.strip()
        if name and name != db.UNUSED and name not in seen:
            seen.append(name)
    return seen


def _resize(tensor: Any, height: int, width: int) -> Any:
    """把单张图缩放到目标尺寸；尺寸相同就直接返回。"""
    if tensor.shape[1] == height and tensor.shape[2] == width:
        return tensor
    import torch.nn.functional as F

    nchw = tensor.permute(0, 3, 1, 2)  # NHWC → NCHW
    resized = F.interpolate(nchw, size=(height, width), mode="bilinear", align_corners=False)
    return resized.permute(0, 2, 3, 1)


def collect(lanes: dict[str, Any]) -> Any:
    """按固定顺序把各路选中的图拼成一个批次；一张都没有就返回阻塞。"""
    tensors: list[Any] = []
    size: tuple[int, int] | None = None
    for lib, _label in LANES:
        for name in _split(lanes.get(lib)):
            try:
                item = db.find(lib, name)
                if item is None:
                    continue
                path, _angle = db.resolve(lib, item)
                image = db.load_pixels(path)
            except Exception as err:  # 单张坏图跳过，不拖累其它图
                print(f"[QQ-预制图像参考] 读取失败（{lib}/{name}）：{err}", flush=True)
                continue
            if size is None:
                size = (int(image.shape[1]), int(image.shape[2]))
            else:
                image = _resize(image, *size)
            tensors.append(image)

    if not tensors:
        return _blocker()
    if len(tensors) == 1:
        return tensors[0]
    import torch

    return torch.cat(tensors, dim=0)


class QQGuliPosePicker:
    CATEGORY = "QQ/图库"
    FUNCTION = "pick"
    RETURN_TYPES = ("IMAGE",)
    RETURN_NAMES = ("参考图",)
    DESCRIPTION = (
        "在一个节点里挑姿态、脸模、服装参考图，每类都能选多张，"
        "按 姿态 → 脸模 → 服装 的顺序拼成一个批次从单路输出。"
        "点类型展开图库、点缩略图多选；一张都没选时输出阻塞。"
        "图片放在 ComfyUI/user/QQ_ComfyUI_Tools/GuliPoses/<类型>/img 下，升级插件不会丢。"
    )

    @classmethod
    def INPUT_TYPES(cls) -> dict[str, Any]:
        return {
            "required": {
                # 由前端画廊写入，多个名字用 | 分隔；手填也认
                "姿态": ("STRING", {"default": "", "multiline": False}),
                "脸模": ("STRING", {"default": "", "multiline": False}),
                "服装": ("STRING", {"default": "", "multiline": False}),
            }
        }

    @classmethod
    def VALIDATE_INPUTS(cls, **kwargs: Any) -> bool:
        # 选项随目录实时变化，旧工作流里可能存着已删掉的条目，不能硬校验。
        return True

    def pick(self, 姿态: str = "", 脸模: str = "", 服装: str = ""):
        return (collect({"pose": 姿态, "face": 脸模, "cloth": 服装}),)


NODE_CLASS_MAPPINGS = {"QQGuliPosePicker": QQGuliPosePicker}
NODE_DISPLAY_NAME_MAPPINGS = {"QQGuliPosePicker": "QQ-预制图像参考"}
